pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address player) public {
        vm.assume(player != address(0) && player != address(c.bank()));
        uint256 initialBankBalance = address(c.bank()).balance;
        uint256 initialPot = c.pot();

        // Fund player with exactly TICKET_AMOUNT
        vm.deal(player, 10);
        vm.prank(player);
        (bool success, ) = address(c).call{value: 10}(abi.encodeWithSignature("play()"));

        if (!success) {
            // revert - pot unchanged, bank unchanged
            assertTrue(c.pot() == initialPot);
            assertTrue(address(c.bank()).balance == initialBankBalance);
        } else {
            uint256 bankIncrease = address(c.bank()).balance - initialBankBalance;
            if (bankIncrease == 1) {
                // payout happened, pot must be 0
                assertTrue(c.pot() == 0);
            } else {
                // no payout, pot increased by 10
                assertTrue(c.pot() == initialPot + 10);
            }
        }
    }
}

